  (function() {
    const items = $input.all();

    if (items.length === 0) {
        return "<i>📭 Belum ada device.</i>";
    }

    // Tag <pre> wajib agar font monospace dan spasi sejajar di Telegram
    let msg = "<pre>\n";
    msg += "No | IP Address      | Brand\n";
    msg += "---------------------------------\n";

    items.forEach(item => {
        const d = item.json;

        // Mengatur lebar karakter dengan spasi agar kolom rata
        const no = String(d.id).padEnd(3, ' ');
        const ip = String(d.address).padEnd(15, ' ');
        const brand = String(d.brand);

        msg += `${no}| ${ip} | ${brand}\n`;
    });

    msg += "</pre>";

    return msg;
  })()
}}
✅ Device berhasil ditambahkan, untuk menghapus dapat menggunakan /remove

