const text = $input.item.json.message.text.trim();
const args = text.split(/\s+/);

// 1. Jika user hanya mengetik "/remove" tanpa spasi dan angka
if (args.length === 1) {
    return { json: { route: "show_list" } };
}

// 2. Mengambil ID dan memastikannya adalah angka bulat (integer)
const idInput = parseInt(args[1], 10);

// 3. Validasi: Tolak jika bukan angka (NaN) atau angkanya 0 / negatif
if (isNaN(idInput) || idInput <= 0) {
    return { json: { 
        route: "error", 
        pesan_error: "❌ <b>Format Salah!</b>\n\nID device harus berupa angka valid.\nContoh: <code>/remove 1</code>" 
    }};
}

// 4. Jika format benar, kirim perintah delete beserta ID-nya
return { json: { 
        route: "delete", 
        id: idInput 
}};

const text = $input.item.json.message.text.trim();
// Memecah pesan berdasarkan spasi
const args = text.split(/\s+/);

// Pengecekan jumlah parameter (Command + 6 parameter = 7)
if (args.length !== 7) {
    return { json: { 
        is_valid: false, 
        pesan_error: "❌ <b>Format Salah!</b>\n\nGunakan format:\n<code>/add (address) (port ssh) (username) (password) (brand) (port ftp)</code>" 
    }};
}

const brandInput = args[5].toLowerCase();
const validBrands = ['mikrotik', 'cisco', 'huawei', 'juniper'];

// Pengecekan brand
if (!validBrands.includes(brandInput)) {
    return { json: { 
        is_valid: false, 
        pesan_error: "❌ <b>Brand tidak didukung!</b>\n\nBrand yang diizinkan hanya: <i>mikrotik, cisco, huawei, juniper</i>." 
    }};
}

// Jika lolos validasi, teruskan data untuk di-insert ke tabel
return { json: {
    is_valid: true,
    address: args[1],
    port: args[2],
    username: args[3],
    password: args[4],
    brand: brandInput,
    portftp: args[6]
}};

